'use strict';
// 0.4.3: station congestion, asset accounting, cancellation recovery and immediate construction undo.
const CONGESTION_LIMIT=180,UNDO_SECONDS=20;
let constructionUndo=null,accountingDepth=0;
const cashRound=n=>Math.round(Math.max(0,n)*100)/100;
function updateCongestion(c,dt){let p=Math.max(0,c.congestionPressure||0),limit=CONGESTION_LIMIT*(c.shape===1?1.25:1),ratio=c.q.filter(p=>!p.cardId).length/Math.max(1,capacity(c));if(c.grace>0||c.shield>0){c.warning=0;return;}if(ratio>=1)p=Math.min(limit,p+dt);else p=Math.max(0,p-dt*(ratio<=.8?2:1));c.congestionPressure=p;c.warning=ratio>=1&&p>=limit-8?limit-p:0;if(p>=limit){S.lives--;c.shield=45;c.congestionPressure=0;c.warning=0;toast(c.name+'候客厅持续满员，扣一条生命 · 本城保护45秒');}}
function remoteCity(c){return !!c.remote||c.x<0||c.name?.endsWith('远城');}
const rateBeforeRemote=passengerRate;passengerRate=function(c){let rate=rateBeforeRemote(c);if(!rate||!remoteCity(c))return rate;let stage=c.stage??c.size;return c.shape===1?.07*.75*Math.pow(1.2,stage)*Math.min(1,.3+Math.max(0,S.day-c.activatedDay)/5):.021*Math.pow(1.15,stage);};
function assetState(){if(S.assetAccounting===1)return;S.stockAssets={};S.recoveryJobs??=[];S.ledger.refunds??=0;
let roads=Object.values(S.infrastructure).filter(x=>x.type!=='air'),known=S.bridges.reduce((n,b)=>n+(b.price||0),0)+realCities().reduce((n,c)=>n+(c.school?3800:0)+(c.repairCenter?5000:0)+(c.meteo?2600+(c.meteo>1?3200:0):0)+(c.hub?3500:0),0)+(S.eventArchive||[]).reduce((n,e)=>n+(e.cost||0),0)+(S.event?.cost||0);
let estimates=roads.map(x=>{let a=S.cities[x.a],b=S.cities[x.b];return 10*Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)*(x.type==='track'?.65:.38))+(requirements(a,b,x.type==='track'?'emu':'bus').tunnel||0)*2200;}),total=estimates.reduce((a,b)=>a+b,0),scale=Math.min(1,Math.max(0,(S.ledger.construction||0)-known)/Math.max(1,total));roads.forEach((x,i)=>{if(x.investment===undefined){x.investment=Math.floor(estimates[i]*scale*100)/100;x.legacyInvestment=true;}});
let assets=S.vehicles.map(v=>({v,type:v.type,cars:v.cars}));for(let type of ['bus','emu','rail','air']){S.stockAssets[type]=[];for(let i=0;i<(S.inventory[type]||0);i++)assets.push({type,cars:isTrain(type)?2:1});}let sum=assets.reduce((n,a)=>n+TYPES[a.type].vehicle+Math.max(0,a.cars-2)*(a.type==='emu'?700:1100),0),factor=Math.min(1,(S.ledger.vehicles||0)/Math.max(1,sum));for(let a of assets){let value=Math.floor((TYPES[a.type].vehicle+Math.max(0,a.cars-2)*(a.type==='emu'?700:1100))*factor*100)/100;if(a.v){a.v.investment??=value;a.v.legacyInvestment=true;}else S.stockAssets[a.type].push({cars:a.cars,investment:value,legacyInvestment:true});}S.assetAccounting=1;}
function takeStockAsset(type){assetState();let pool=S.stockAssets[type]??=[];return pool.shift()||{cars:isTrain(type)?2:1,investment:0};}
function addStockAsset(type,asset){assetState();(S.stockAssets[type]??=[]).push({...asset});}
function retireVehicleAsset(v){if(v.assetReturned)return;assetState();v.assetReturned=true;v.retired=true;if(v.recoveryMode==='sell'){let amount=cashRound((v.investment||0)*.7);credit(amount,'refunds',TYPES[v.type].name+'及车厢70%回收');}else{S.inventory[v.type]++;addStockAsset(v.type,{cars:v.cars,investment:v.investment||0,legacyInvestment:!!v.legacyInvestment});}}
const freshBeforeManagement=fresh;fresh=function(){let x=freshBeforeManagement();x.assetAccounting=1;x.stockAssets={bus:[],emu:[],rail:[],air:[]};x.recoveryJobs=[];x.ledger.refunds=0;return x;};
const spendBeforeManagement=spend;spend=function(...args){assetState();if(!accountingDepth)constructionUndo=null;return spendBeforeManagement(...args);};
function lineEdgeKeys(l){return [...new Set(l.stops.slice(1).map((id,i)=>key(S.cities[l.stops[i]],S.cities[id],l.type)))].filter(k=>!!S.infrastructure[k]);}
function otherLineUses(k,ignore){return S.lines.some(l=>l.id!==ignore&&l.stops.some((id,i)=>i&&key(S.cities[l.stops[i-1]],S.cities[id],l.type)===k));}
function cancellationQuote(id){assetState();let l=S.lines.find(l=>l.id===id);if(!l)return null;let roads=lineEdgeKeys(l).filter(k=>!otherLineUses(k,id)),vehicles=S.vehicles.filter(v=>v.line===id&&!v.retired);return {roads,roadRefund:cashRound(roads.reduce((n,k)=>n+(S.infrastructure[k].investment||0)*.5,0)),vehicleRefund:cashRound(vehicles.reduce((n,v)=>n+(v.investment||0)*.7,0)),legacy:roads.some(k=>S.infrastructure[k].legacyInvestment)||vehicles.some(v=>v.legacyInvestment)};}
function showLineCancellation(id){let l=S.lines.find(l=>l.id===id),q=cancellationQuote(id);if(!l||l.retiring||!q)return;openModal(`<div class="modal-head"><h2>取消 ${escapeHTML(l.name)}</h2><button class="close" onclick="closeModal()">×</button></div><p>车辆到下一座城市正常下客后退出。独立桥梁保留，可从桥梁信息另行拆除。</p><div class="quote-row"><span>闲置道路/铁路及升级 · 50%</span><b>预计 ¥${q.roadRefund.toFixed(2)}</b></div><div class="quote-row"><span>车辆及车厢 · 70%</span><b>预计 ¥${q.vehicleRefund.toFixed(2)}</b></div><p>共享路段不拆、不退。维护费不退，正在施工的路段完工后回收；最终按实际闲置资产结算。${q.legacy?'旧存档缺少分项发票的资产采用保守分摊，金额受历史实际支出上限约束。':''}</p><div class="ux-actions"><button class="primary" onclick="confirmLineCancellation(${id},true)">取消并回收 · 预计 ¥${cashRound(q.roadRefund+q.vehicleRefund)}</button><button onclick="confirmLineCancellation(${id},false)">仅取消，保留道路和车辆</button><button onclick="closeModal()">返回</button></div>`);}
function confirmLineCancellation(id,recover){let l=S.lines.find(l=>l.id===id);if(!l||l.retiring)return;assetState();let q=cancellationQuote(id);constructionUndo=null;l.retiring=true;for(let v of S.vehicles.filter(v=>v.line===id))v.recoveryMode=recover?'sell':'stock';if(recover)S.recoveryJobs.push({line:id,roads:q.roads});for(let v of S.vehicles.filter(v=>v.line===id)){if(v.t===0){arrival(v,vehicleLine(v));}else if(!v.people.length)v.recall=true;}S.vehicles=S.vehicles.filter(v=>!v.retired);if(!S.vehicles.some(v=>v.line===id))S.lines=S.lines.filter(x=>x.id!==id);settleRecoveryJobs();closeModal();clearSelection();updateUI();save();toast(recover?'线路退出中 · 到站回收车辆、闲置路段按比例退款':'线路退出中 · 车辆回库存，道路保留复用');}
deleteLine=function(id){showLineCancellation(id);};
function settleRecoveryJobs(){assetState();let remain=[];for(let job of S.recoveryJobs){if(S.vehicles.some(v=>v.line===job.line)){remain.push(job);continue;}let pending=[];for(let k of job.roads){let x=S.infrastructure[k];if(!x||otherLineUses(k,job.line))continue;if(x.until>S.day||S.vehicles.some(v=>currentEdge(v)===k)){pending.push(k);continue;}let amount=cashRound((x.investment||0)*.5);delete S.infrastructure[k];delete S.corridors[k];delete S.blockages[k];credit(amount,'refunds','闲置路段50%回收');}if(pending.length)remain.push({...job,roads:pending});}S.recoveryJobs=remain;}
const removeRoadBeforeManagement=removeUnusedRoad;removeUnusedRoad=function(k){assetState();let x=S.infrastructure[k];if(!x||!unusedRoad(k)||x.until>S.day)return;let amount=cashRound((x.investment||0)*.5);removeRoadBeforeManagement(k);if(!S.infrastructure[k]){credit(amount,'refunds','闲置路段50%回收');save();showMaintenance();}};
const arrivalBeforeManagement=arrival;arrival=function(v,l){if(v.people.length)v.hasTransported=true;arrivalBeforeManagement(v,l);if(v.people.length)v.hasTransported=true;};
const tickBeforeManagement=tick;tick=function(dt){assetState();for(let v of S.vehicles)if(v.people.length)v.hasTransported=true;tickBeforeManagement(dt);for(let v of S.vehicles){let l=vehicleLine(v);if(l&&(l.retiring||v.recall)&&v.t===0&&S.cities[l.stops[v.index]]?.kind==='bridgehead'&&departureIndex(v,l)<0){let head=S.cities[l.stops[v.index]],safe=realCities().filter(c=>!c.dormant&&(typeof activeAtlasMap!=='undefined'&&activeAtlasMap?!requirements(head,c,'bus').bridge:pointBank(c)===pointBank(head))).sort((a,b)=>Math.hypot(a.x-head.x,a.y-head.y)-Math.hypot(b.x-head.x,b.y-head.y))[0];if(safe){for(let p of v.people){if(!finishPassengerAtCity(p,safe)){p.ready=2;safe.q.push(p);}}v.people=[];retireVehicleAsset(v);}}}S.vehicles=S.vehicles.filter(v=>!v.retired);S.lines=S.lines.filter(l=>!l.retiring||S.vehicles.some(v=>v.line===l.id));settleRecoveryJobs();};
function offerConstructionUndo(receipt){constructionUndo={...receipt,expires:performance.now()+UNDO_SECONDS*1000};showUndoBuild();}
function showUndoBuild(){let b=$('undo-build');if(!b)return;let u=constructionUndo;b.hidden=!u||performance.now()>u.expires;if(!b.hidden)b.textContent='撤回'+u.label+' · '+Math.ceil((u.expires-performance.now())/1000)+'秒 · 全退 ¥'+u.paid;}
function undoConstruction(){let u=constructionUndo;if(!u||performance.now()>u.expires){constructionUndo=null;showUndoBuild();return toast('撤回时间已过，取消线路可选择部分回收');}if(!u.canUndo())return toast('该建设已投入运输或被共用，请使用取消线路部分回收');u.undo();if(u.lineId!==undefined){routeGhosts=routeGhosts.filter(g=>g.line.id!==u.lineId);if(stopUndo?.lineId===u.lineId)stopUndo=null;}constructionUndo=null;credit(u.paid,'refunds','撤回'+u.label+'全额退款');updateUI();showUndoBuild();save();toast('已撤回'+u.label+' · 全额返还 ¥'+u.paid);}
const commitBeforeManagement=commitDraft;commitDraft=function(skip=false){if(!draft)return;assetState();let d={...draft,stops:[...draft.stops]},cost=draftCost(),priorKeys=new Set(Object.keys(S.infrastructure)),ids=new Set(S.vehicles.map(v=>v.id)),cash=S.points,oldLine=d.original&&S.lines.find(l=>l.id===d.original),oldStops=oldLine&&[...oldLine.stops],oldCities=S.cities.filter(c=>c.dormant).map(c=>c.id),oldTunnelStock=S.inventory.tunnel;accountingDepth++;try{commitBeforeManagement(skip);}finally{accountingDepth--;}if(draft)return;constructionUndo=null;let newKeys=Object.keys(S.infrastructure).filter(k=>!priorKeys.has(k)),paid=cashRound(cash-S.points),roadPaid=Math.max(0,paid-(cost.vehicle||0)),weight=newKeys.map(k=>{let x=S.infrastructure[k],a=S.cities[x.a],b=S.cities[x.b];return Math.hypot(a.x-b.x,a.y-b.y)*(x.type==='track'?.65:.38)+(requirements(a,b,x.type==='track'?'emu':'bus').tunnel||0)*220;}),sum=weight.reduce((n,a)=>n+a,0),allocated=0;newKeys.forEach((k,i)=>{let value=i===newKeys.length-1?cashRound(roadPaid-allocated):Math.floor(roadPaid*weight[i]/Math.max(1,sum)*100)/100;S.infrastructure[k].investment=value;allocated+=value;});let tunnelUsed=Math.max(0,oldTunnelStock-S.inventory.tunnel),line=oldLine||S.lines.at(-1),newVehicles=S.vehicles.filter(v=>!ids.has(v.id));if(!paid&&!oldLine)return;if(d.stopRemoval&&stopUndo?.lineId===line.id)stopUndo.newKeys=[...newKeys];offerConstructionUndo({label:oldLine?'改线':'建线',lineId:line.id,paid,canUndo:()=>S.lines.includes(line)&&!line.retiring&&!newKeys.some(k=>otherLineUses(k,line.id))&&(oldLine?!newKeys.some(k=>S.vehicles.some(v=>currentEdge(v)===k)):S.vehicles.filter(v=>v.line===line.id).every(v=>newVehicles.includes(v)&&!v.people.length&&!v.hasTransported)),undo:()=>{if(oldLine){for(let v of S.vehicles.filter(v=>v.line===line.id))unloadForEdit(v,line);line.stops=oldStops;}else{S.lines=S.lines.filter(l=>l.id!==line.id);for(let v of newVehicles){if(!cost.vehicle){S.inventory[v.type]++;addStockAsset(v.type,{cars:v.cars,investment:v.investment||0});}}S.vehicles=S.vehicles.filter(v=>!newVehicles.includes(v));}S.inventory.tunnel+=tunnelUsed;for(let k of newKeys){delete S.infrastructure[k];delete S.corridors[k];delete S.blockages[k];}for(let id of oldCities){let c=S.cities[id];if(!S.lines.some(l=>l.stops.includes(id))&&!c.q.length)c.dormant=true;}clearSelection();}});save();};
const upgradeBeforeManagement=startUpgrade;startUpgrade=function(k,id){assetState();let x=S.infrastructure[k];if(!x)return;let before={...x},cash=S.points;accountingDepth++;try{upgradeBeforeManagement(k,id);}finally{accountingDepth--;}let paid=cashRound(cash-S.points);if(!paid)return;x.investment=(before.investment||0)+paid;offerConstructionUndo({label:'升级',paid,canUndo:()=>S.infrastructure[k]===x&&x.until>S.day,undo:()=>{S.infrastructure[k]=before;closeModal();}});save();};
const bridgeBeforeManagement=createBridge;createBridge=function(){let cash=S.points,n=S.nextBridge;accountingDepth++;try{bridgeBeforeManagement();}finally{accountingDepth--;}let bridge=S.bridges.find(b=>b.id===n),paid=cashRound(cash-S.points);if(!bridge||!paid)return;offerConstructionUndo({label:'建桥',paid,canUndo:()=>bridge.status==='open'&&!S.lines.some(l=>bridge.heads.some(id=>l.stops.includes(id))),undo:()=>{bridge.status='removed';bridge.heads.forEach(id=>S.cities[id].removed=true);clearSelection();}});};
const bridgeUpgradeBeforeManagement=startBridgeUpgrade;startBridgeUpgrade=function(id){let x=S.bridges.find(b=>b.id===id);if(!x)return;let before={...x},cash=S.points;accountingDepth++;try{bridgeUpgradeBeforeManagement(id);}finally{accountingDepth--;}let paid=cashRound(cash-S.points);if(paid)offerConstructionUndo({label:'桥面升级',paid,canUndo:()=>x.until>S.day&&x.status==='open',undo:()=>{for(let k of Object.keys(x))delete x[k];Object.assign(x,before);closeModal();clearSelection();}});};
const loadBeforeManagement=load;load=function(){let ok=loadBeforeManagement();if(ok){assetState();for(let c of realCities()){c.warning=0;c.congestionPressure??=0;}save();}return ok;};
const resetBeforeManagement=reset;reset=function(){constructionUndo=null;resetBeforeManagement();};
const uiBeforeManagement=updateUI;updateUI=function(){uiBeforeManagement();showUndoBuild();};
const financeBeforeManagement=showFinance;showFinance=function(){financeBeforeManagement();$('modal-content').innerHTML+=`<div class="quote-row"><span>撤回/回收返还</span><b>+¥${S.ledger.refunds||0}</b></div>`;};
$('finance').onclick=()=>showFinance();$('undo-build').onclick=undoConstruction;
assetState();

for(let c of realCities()){c.warning=0;c.congestionPressure??=0;}

function normalizeDormantRemoteCities(){if(S.remoteProgressVersion===1)return;let moved=false;for(let c of realCities()){if(!remoteCity(c)||!c.dormant||c.q.length||c.school||c.repairCenter||c.meteo||c.hub||S.lines.some(l=>l.stops.includes(c.id))||Object.values(S.infrastructure).some(x=>x.a===c.id||x.b===c.id))continue;let others=realCities().filter(x=>x.id!==c.id),active=others.filter(x=>!x.dormant),nearest=Math.min(...active.map(a=>Math.hypot(a.x-c.x,a.y-c.y)));if(nearest<=410)continue;let p=remoteSpawnPoint(others);if(p){c.x=p.x;c.y=p.y;c.remote=true;c.remoteStage=p.stage;moved=true;}}S.remoteProgressVersion=1;if(moved)fit();save();}
const loadBeforeRemoteProgression=load;load=function(){let ok=loadBeforeRemoteProgression();if(ok)normalizeDormantRemoteCities();return ok;};
normalizeDormantRemoteCities();

function hubLimit(){return 3+(S.activityCards?.bonuses.hub||0);}

// Undo must restore physical route beds as well as the coloured line.
function cleanUndoRoads(){let pending=[];for(let k of S.undoRoadCleanup||[]){if(!S.infrastructure[k])continue;if(S.lines.some(l=>lineEdgeKeys(l).includes(k)))continue;if(S.vehicles.some(v=>currentEdge(v)===k)){pending.push(k);continue;}delete S.infrastructure[k];delete S.corridors[k];delete S.blockages[k];}S.undoRoadCleanup=pending;}
const undoStopBeforeRoadCleanup=undoStopRemoval;undoStopRemoval=function(){let u=stopUndo,l=u&&S.lines.find(l=>l.id===u.lineId),valid=u&&performance.now()<=u.expires&&l&&!l.retiring&&l.stops.join(',')===u.after.join(',');undoStopBeforeRoadCleanup();if(!valid)return;S.undoRoadCleanup=[...new Set([...(S.undoRoadCleanup||[]),...(u.newKeys||[])])];cleanUndoRoads();if(constructionUndo?.lineId===u.lineId)constructionUndo=null;showUndoBuild();save();};
const tickBeforeUndoRoadCleanup=tick;tick=function(dt){tickBeforeUndoRoadCleanup(dt);cleanUndoRoads();};
